import{_ as i,c as e,o as a,ag as o}from"./chunks/framework.B1jFR3yW.js";const p=JSON.parse('{"title":"Linux","description":"","frontmatter":{},"headers":[],"relativePath":"计划/计算机基础/linux.md","filePath":"计划/计算机基础/linux.md"}'),d={name:"计划/计算机基础/linux.md"};function c(t,l,r,u,h,n){return a(),e("div",null,[...l[0]||(l[0]=[o('<h1 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h1><blockquote><p>对个人开发者来说，Linux 的目标很明确：你要能把服务部署上去，并且出了问题能自己查。</p></blockquote><h2 id="你需要掌握什么" tabindex="-1">你需要掌握什么 <a class="header-anchor" href="#你需要掌握什么" aria-label="Permalink to &quot;你需要掌握什么&quot;">​</a></h2><h3 id="_1-目录结构和文件操作" tabindex="-1">1. 目录结构和文件操作 <a class="header-anchor" href="#_1-目录结构和文件操作" aria-label="Permalink to &quot;1. 目录结构和文件操作&quot;">​</a></h3><ul><li>常见目录作用：<code>/home</code>、<code>/etc</code>、<code>/var</code>、<code>/usr</code>、<code>/tmp</code></li><li>当前目录、绝对路径、相对路径</li><li>创建、复制、移动、删除文件和目录</li><li>查看文件内容：<code>cat</code>、<code>less</code>、<code>tail</code></li><li>搜索文件：<code>find</code>、<code>rg</code></li></ul><p>至少要熟练：</p><ul><li>找到配置文件、日志文件、项目目录</li><li>看日志、改配置、备份文件</li></ul><h3 id="_2-权限管理" tabindex="-1">2. 权限管理 <a class="header-anchor" href="#_2-权限管理" aria-label="Permalink to &quot;2. 权限管理&quot;">​</a></h3><ul><li><code>rwx</code> 权限含义</li><li><code>chmod</code>、<code>chown</code>、<code>chgrp</code></li><li>用户与用户组</li><li><code>sudo</code> 的使用场景</li></ul><p>至少要理解：</p><ul><li>为什么文件能看不能改</li><li>为什么服务能启动但读不到某个目录</li></ul><h3 id="_3-进程管理" tabindex="-1">3. 进程管理 <a class="header-anchor" href="#_3-进程管理" aria-label="Permalink to &quot;3. 进程管理&quot;">​</a></h3><ul><li><code>ps</code>、<code>top</code>、<code>htop</code></li><li><code>kill</code>、<code>kill -9</code></li><li>后台运行：<code>nohup</code>、<code>&amp;</code></li><li>端口与进程关系：<code>lsof</code>、<code>ss</code>、<code>netstat</code></li></ul><p>至少要能做到：</p><ul><li>找到某个服务是否在运行</li><li>查出哪个进程占了端口</li><li>杀掉异常进程并重新启动服务</li></ul><h3 id="_4-日志与排障" tabindex="-1">4. 日志与排障 <a class="header-anchor" href="#_4-日志与排障" aria-label="Permalink to &quot;4. 日志与排障&quot;">​</a></h3><ul><li><code>tail -f</code> 实时看日志</li><li><code>grep</code> / <code>rg</code> 搜索错误信息</li><li>查看系统日志和服务日志</li><li>区分应用报错、权限报错、网络报错、磁盘报错</li></ul><p>至少要养成习惯：</p><ul><li>出问题先看日志，不凭感觉改代码</li></ul><h3 id="_5-网络相关" tabindex="-1">5. 网络相关 <a class="header-anchor" href="#_5-网络相关" aria-label="Permalink to &quot;5. 网络相关&quot;">​</a></h3><ul><li>IP、端口、域名、DNS 的关系</li><li><code>curl</code> 测试接口</li><li><code>ping</code>、<code>traceroute</code> 基本用途</li><li>防火墙、安全组、监听地址的概念</li></ul><p>至少要会排查：</p><ul><li>服务启动了但外部访问不到</li><li>域名解析正常但接口超时</li><li>本机能访问，公网不能访问</li></ul><h3 id="_6-包管理和环境管理" tabindex="-1">6. 包管理和环境管理 <a class="header-anchor" href="#_6-包管理和环境管理" aria-label="Permalink to &quot;6. 包管理和环境管理&quot;">​</a></h3><ul><li><code>apt</code>、<code>yum</code> 的基本使用</li><li>软件安装、升级、卸载</li><li>Node.js、Python、数据库等运行环境安装</li><li>环境变量配置：<code>PATH</code>、<code>NODE_ENV</code> 等</li></ul><p>至少要能完成：</p><ul><li>配置一台新机器的基础开发和运行环境</li></ul><h3 id="_7-shell-基础" tabindex="-1">7. Shell 基础 <a class="header-anchor" href="#_7-shell-基础" aria-label="Permalink to &quot;7. Shell 基础&quot;">​</a></h3><ul><li>常见命令组合使用</li><li>重定向：<code>&gt;</code>、<code>&gt;&gt;</code></li><li>管道：<code>|</code></li><li>通配符和变量</li><li>简单 Bash 脚本</li></ul><p>至少要能写：</p><ul><li>启动脚本</li><li>部署脚本</li><li>备份脚本</li></ul><h3 id="_8-服务部署基础" tabindex="-1">8. 服务部署基础 <a class="header-anchor" href="#_8-服务部署基础" aria-label="Permalink to &quot;8. 服务部署基础&quot;">​</a></h3><ul><li>Nginx 基本反向代理</li><li><code>systemd</code> 服务管理</li><li>进程守护和开机启动</li><li>HTTPS 证书续期的基本流程</li><li>Docker 常见命令和容器排查</li></ul><p>至少要会做：</p><ul><li>部署前端静态站点</li><li>部署 Node.js API 服务</li><li>反向代理域名到服务端口</li></ul><h2 id="作为前端转全栈的学习重点" tabindex="-1">作为前端转全栈的学习重点 <a class="header-anchor" href="#作为前端转全栈的学习重点" aria-label="Permalink to &quot;作为前端转全栈的学习重点&quot;">​</a></h2><h3 id="优先级最高" tabindex="-1">优先级最高 <a class="header-anchor" href="#优先级最高" aria-label="Permalink to &quot;优先级最高&quot;">​</a></h3><ul><li>文件操作</li><li>日志查看</li><li>进程管理</li><li>端口排查</li><li>网络联通性检查</li><li>Nginx 基础配置</li></ul><h3 id="第二优先级" tabindex="-1">第二优先级 <a class="header-anchor" href="#第二优先级" aria-label="Permalink to &quot;第二优先级&quot;">​</a></h3><ul><li>Shell 脚本</li><li><code>systemd</code></li><li>Docker</li><li>定时任务 <code>crontab</code></li></ul><h3 id="第三优先级" tabindex="-1">第三优先级 <a class="header-anchor" href="#第三优先级" aria-label="Permalink to &quot;第三优先级&quot;">​</a></h3><ul><li>更深入的系统调优</li><li>内核参数</li><li>复杂权限和安全策略</li></ul><h2 id="判断自己是否掌握" tabindex="-1">判断自己是否掌握 <a class="header-anchor" href="#判断自己是否掌握" aria-label="Permalink to &quot;判断自己是否掌握&quot;">​</a></h2><ul><li>你能独立把一个前后端项目部署到 Linux 服务器</li><li>你能根据日志定位大多数启动失败问题</li><li>你能查出端口占用、权限不足、磁盘空间不足、域名或反向代理配置错误</li><li>你能写出简单可维护的部署脚本</li></ul>',44)])])}const _=i(d,[["render",c]]);export{p as __pageData,_ as default};
